// src/context/GlobalContext.js
import React, { createContext, useReducer, useContext, useEffect } from "react";
import { supabase } from "../../lib/supabaseClient";

const GlobalContext = createContext();

// Key for localStorage
const STORAGE_KEY = 'globalState';

const initialState = {
  cart: [],
  wishlist: [],
  user: null,
  checkoutDetails: {
    cart: [],
    shippingAddress: null,
    paymentMethod: null,
    orderSummary: {
      subtotal: 0,
      shippingCost: 0,
      total: 0,
    },
  }
};

export function deepEqual(obj1, obj2) {
  const keys1 = Object.keys(obj1).sort();
  const keys2 = Object.keys(obj2).sort();

  if (keys1.length !== keys2.length) return false;
  for (let i = 0; i < keys1.length; i++) {
    const k = keys1[i];
    if (k !== keys2[i]) return false;
    if (obj1[k] !== obj2[k]) return false;
  }
  return true;
}



// Load state from localStorage (SSR safe)
const loadState = () => {
  if (typeof window === 'undefined') return initialState;
  try {
    const serializedState = localStorage.getItem(STORAGE_KEY);
    return serializedState ? JSON.parse(serializedState) : initialState;
  } catch (e) {
    console.warn("Failed to load state from localStorage", e);
    return initialState;
  }
};

function reducer(state, action) {
  let newState;
  switch (action.type) {
    case "ADD_TO_CART": {
      const exists = state.cart.find(item => item.id === action.payload.id);
      if (exists) {
        newState = {
          ...state,
          cart: state.cart.map(item =>
            item.id === action.payload.id
              ? { ...item, quantity: item.quantity + 1 }
              : item
          ),
        };
      } else {
        newState = {
          ...state,
          cart: [...state.cart, { ...action.payload, quantity: 1 }],
        };
      }
      break;
    }
    case "PRINT_CART": {
      console.log("🛒 CART CONTENTS:", state.cart);
      newState = state; // no changes to state
      break;
    }
    case "REMOVE_FROM_CART":
      newState = {
        ...state,
        cart: state.cart.filter(item =>
          !(
            item.id === action.payload.id &&
            deepEqual(item.options, action.payload.options)
          )
        ),
      };
      break;
    case "ADD_TO_CART_AS_UNIQUE": {
      newState = {
        ...state,
        cart: [...state.cart, { ...action.payload, quantity: 1 }],
      };
      break;
    }
    case "SET_CART":
       newState = {
          ...state,
          cart: [{ ...action.payload, quantity: 1 }],
      };
      break;

    case "UPDATE_CART_ITEM":
      newState = {
        ...state,
        cart: state.cart.map(item =>
          item.id === action.payload.id
            ? { ...item, quantity: action.payload.quantity }
            : item
        ),
      };
      break;
    
      case "RESET_CART":
      newState = {
        ...state,
        cart: [],
      };
      break;

    case "CHECKOUT_CART_DETAILS":
      newState = {
        ...state,
        checkoutDetails: {
          ...state.checkoutDetails,
          cart: state.cart,
          shippingAddress: action.payload.shippingAddress || state.checkoutDetails.shippingAddress,
          paymentMethod: action.payload.paymentMethod,
          orderSummary: {
            subtotal: action.payload.orderSummary.subtotal || 0,
            shippingCost: action.payload.orderSummary.shippingCost || 0,
            total: action.payload.orderSummary.total || 0,
          },
        },
      };
      break;

    case "SET_USER":
      newState = {
        ...state,
        userLoginData: action.payload,
      };
      break;

    case "LOGOUT":
      newState = {
        ...state,
        userLoginData: null,
      };
      break;

    default:
      newState = state;
  }

  return newState;
}

export const GlobalProvider = ({ children }) => {
  const [state, dispatch] = useReducer(reducer, loadState());

  // Save state to localStorage whenever it changes (SSR safe)
  useEffect(() => {
    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      } catch (e) {
        console.warn("Failed to save state to localStorage", e);
      }
    }
  }, [state]);

  // Supabase auth load
  useEffect(() => {
    const loadUser = async () => {
      const { data, error } = await supabase.auth.getUser();
      if (data?.user) {
        dispatch({ type: "SET_USER", payload: data.user });
      } else {
        dispatch({ type: "LOGOUT" });
      }
    };

    loadUser();

    const { data: authListener } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        dispatch({ type: "SET_USER", payload: session.user });
      } else {
        dispatch({ type: "LOGOUT" });
      }
    });

    return () => {
      authListener.subscription.unsubscribe();
    };
  }, []);

  console.log("GlobalProvider state:", state);

  return (
    <GlobalContext.Provider value={{ state, dispatch }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => useContext(GlobalContext);
